// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Carry the safe local execution-runtime observation into the existing admin shell
	// (GET /admin/execution-runtime)
	GetLegacyExecutionRuntimePage(ctx context.Context, request GetLegacyExecutionRuntimePageRequestObject) (GetLegacyExecutionRuntimePageResponseObject, error)
	// List real D01 Automation trigger receipts through the frozen legacy path
	// (GET /api/admin/automation-conversion/agent-runs)
	ListAutomationTriggerRuns(ctx context.Context, request ListAutomationTriggerRunsRequestObject) (ListAutomationTriggerRunsResponseObject, error)
	// Read the frozen observed execution runtime without invoking a worker or provider
	// (GET /api/admin/execution-runtime)
	GetLegacyExecutionRuntime(ctx context.Context, request GetLegacyExecutionRuntimeRequestObject) (GetLegacyExecutionRuntimeResponseObject, error)
	// Read one frozen observed execution timeline without asserting a provider receipt
	// (GET /api/admin/executions/{execution_id})
	GetLegacyExecutionTimeline(ctx context.Context, request GetLegacyExecutionTimelineRequestObject) (GetLegacyExecutionTimelineResponseObject, error)
	// Read the frozen global Push Center section aggregation without touching a worker or provider
	// (GET /api/admin/push-center/sections)
	GetLegacyPushCenterSections(ctx context.Context, request GetLegacyPushCenterSectionsRequestObject) (GetLegacyPushCenterSectionsResponseObject, error)
	// Read the frozen global Push Center statistics without accepting, sending, or retrying work
	// (GET /api/admin/push-center/stats)
	GetLegacyPushCenterStats(ctx context.Context, request GetLegacyPushCenterStatsRequestObject) (GetLegacyPushCenterStatsResponseObject, error)
	// List non-secret configuration readiness
	// (GET /api/v1/admin/config/overview)
	GetAdminConfigOverview(ctx context.Context, request GetAdminConfigOverviewRequestObject) (GetAdminConfigOverviewResponseObject, error)
	// Invalidate the current admin session
	// (POST /api/v1/auth/logout)
	LogoutAdmin(ctx context.Context, request LogoutAdminRequestObject) (LogoutAdminResponseObject, error)
	// Return the authenticated admin principal
	// (GET /api/v1/auth/session)
	GetAuthSession(ctx context.Context, request GetAuthSessionRequestObject) (GetAuthSessionResponseObject, error)
	// List customers using a keyset cursor
	// (GET /api/v1/customers)
	ListCustomers(ctx context.Context, request ListCustomersRequestObject) (ListCustomersResponseObject, error)
	// Get a channel-neutral customer by OneID
	// (GET /api/v1/customers/{customer_id})
	GetCustomer(ctx context.Context, request GetCustomerRequestObject) (GetCustomerResponseObject, error)
	// Update customer-owned profile fields
	// (PATCH /api/v1/customers/{customer_id})
	UpdateCustomer(ctx context.Context, request UpdateCustomerRequestObject) (UpdateCustomerResponseObject, error)
	// List append-only customer events using a keyset cursor
	// (GET /api/v1/customers/{customer_id}/events)
	ListCustomerEvents(ctx context.Context, request ListCustomerEventsRequestObject) (ListCustomerEventsResponseObject, error)
	// Set or clear a customer's stage
	// (PUT /api/v1/customers/{customer_id}/stage)
	SetCustomerStage(ctx context.Context, request SetCustomerStageRequestObject) (SetCustomerStageResponseObject, error)
	// Idempotently remove one local tag from a customer
	// (DELETE /api/v1/customers/{customer_id}/tags/{tag_id})
	RemoveCustomerTag(ctx context.Context, request RemoveCustomerTagRequestObject) (RemoveCustomerTagResponseObject, error)
	// Idempotently apply one local tag to a customer
	// (PUT /api/v1/customers/{customer_id}/tags/{tag_id})
	AddCustomerTag(ctx context.Context, request AddCustomerTagRequestObject) (AddCustomerTagResponseObject, error)
	// Bind a scoped identity to a channel-neutral customer
	// (POST /api/v1/identity/bind)
	BindIdentity(ctx context.Context, request BindIdentityRequestObject) (BindIdentityResponseObject, error)
	// Attribute or persist an external event without guessing identity
	// (POST /api/v1/identity/ingest)
	IngestIdentityEvent(ctx context.Context, request IngestIdentityEventRequestObject) (IngestIdentityEventResponseObject, error)
	// List pending identity merge reviews without exposing raw identities
	// (GET /api/v1/identity/merge-reviews)
	ListIdentityMergeReviews(ctx context.Context, request ListIdentityMergeReviewsRequestObject) (ListIdentityMergeReviewsResponseObject, error)
	// Approve one versioned merge review with an explicit primary customer
	// (POST /api/v1/identity/merge-reviews/{review_id}/approve)
	ApproveIdentityMergeReview(ctx context.Context, request ApproveIdentityMergeReviewRequestObject) (ApproveIdentityMergeReviewResponseObject, error)
	// Reject one versioned merge review without changing bindings
	// (POST /api/v1/identity/merge-reviews/{review_id}/reject)
	RejectIdentityMergeReview(ctx context.Context, request RejectIdentityMergeReviewRequestObject) (RejectIdentityMergeReviewResponseObject, error)
	// Resolve one scoped identity without implicit creation
	// (POST /api/v1/identity/resolve)
	ResolveIdentity(ctx context.Context, request ResolveIdentityRequestObject) (ResolveIdentityResponseObject, error)
	// List ordinary products using a keyset cursor
	// (GET /api/v1/products)
	ListProducts(ctx context.Context, request ListProductsRequestObject) (ListProductsResponseObject, error)
	// Create one ordinary product
	// (POST /api/v1/products)
	CreateProduct(ctx context.Context, request CreateProductRequestObject) (CreateProductResponseObject, error)
	// Get one ordinary product
	// (GET /api/v1/products/{product_id})
	GetProduct(ctx context.Context, request GetProductRequestObject) (GetProductResponseObject, error)
	// List materialized audience definitions with a keyset cursor
	// (GET /api/v1/segments)
	ListSegments(ctx context.Context, request ListSegmentsRequestObject) (ListSegmentsResponseObject, error)
	// Create one declarative audience definition
	// (POST /api/v1/segments)
	CreateSegment(ctx context.Context, request CreateSegmentRequestObject) (CreateSegmentResponseObject, error)
	// Get one declarative audience definition
	// (GET /api/v1/segments/{segment_id})
	GetSegment(ctx context.Context, request GetSegmentRequestObject) (GetSegmentResponseObject, error)
	// Update one declarative audience definition
	// (PATCH /api/v1/segments/{segment_id})
	UpdateSegment(ctx context.Context, request UpdateSegmentRequestObject) (UpdateSegmentResponseObject, error)
	// Preview the current materialized members using a keyset cursor
	// (GET /api/v1/segments/{segment_id}/members)
	ListSegmentMembers(ctx context.Context, request ListSegmentMembersRequestObject) (ListSegmentMembersResponseObject, error)
	// Durably request one materialized audience refresh
	// (POST /api/v1/segments/{segment_id}/refresh)
	RequestSegmentRefresh(ctx context.Context, request RequestSegmentRefreshRequestObject) (RequestSegmentRefreshResponseObject, error)
	// List global customer stages in deterministic order
	// (GET /api/v1/stages)
	ListStages(ctx context.Context, request ListStagesRequestObject) (ListStagesResponseObject, error)
	// Create one global customer stage
	// (POST /api/v1/stages)
	CreateStage(ctx context.Context, request CreateStageRequestObject) (CreateStageResponseObject, error)
	// Rename one global customer stage
	// (PATCH /api/v1/stages/{stage_id})
	RenameStage(ctx context.Context, request RenameStageRequestObject) (RenameStageResponseObject, error)
	// List the local tag catalog in deterministic order
	// (GET /api/v1/tags)
	ListTags(ctx context.Context, request ListTagsRequestObject) (ListTagsResponseObject, error)
	// Read the public legacy configuration-derived runtime-mode snapshot
	// (GET /health)
	GetLegacyHealth(ctx context.Context, request GetLegacyHealthRequestObject) (GetLegacyHealthResponseObject, error)
	// Read one WeChat or WeCom domain verification file
	// (GET /{filename})
	GetDomainVerificationFile(ctx context.Context, request GetDomainVerificationFileRequestObject) (GetDomainVerificationFileResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

